import { screen } from "@testing-library/react";
import { describe, expect, it } from "vitest";
import { renderWithProviders } from "../../../tests/utils";
import { ConversationEventType, type ConversationEvent } from "../../../types";
import { SlotEvent } from "./SlotEvent";

function slotEvent(overrides: Partial<ConversationEvent>): ConversationEvent {
  return {
    id: "e1",
    conversationEventType: ConversationEventType.Slot,
    name: "amount",
    slotValue: "100",
    actionText: "",
    flowId: "",
    stepId: "",
    timestamp: "2020-01-01T00:00:00.000Z",
    originalTimestamp: 0,
    metadata: { parseData: {} },
    __typename: "ConversationEvent",
    ...overrides,
  };
}

describe("SlotEvent wording", () => {
  it("uses the v1 slot wording", () => {
    renderWithProviders(<SlotEvent event={slotEvent({})} isSelected={false} />);
    expect(screen.getByText(/^Slot/)).toBeInTheDocument();
    expect(screen.getByText("amount")).toBeInTheDocument();
    expect(screen.getByText(/set/)).toBeInTheDocument();
  });

  it("keeps housekeeping slot rows visible", () => {
    const { container } = renderWithProviders(
      <SlotEvent
        event={slotEvent({ name: "consecutive_silence_timeouts", slotValue: "0" })}
        isSelected={false}
      />,
    );
    expect(container.textContent).toContain("consecutive_silence_timeouts");
  });

  it("renders a cleared slot without a value", () => {
    renderWithProviders(<SlotEvent event={slotEvent({ slotValue: null })} isSelected={false} />);
    expect(screen.getByText(/is cleared/)).toBeInTheDocument();
  });

  it("renders a reset-slots row", () => {
    renderWithProviders(
      <SlotEvent
        event={slotEvent({ conversationEventType: ConversationEventType.ResetSlots })}
        isSelected={false}
      />,
    );
    expect(screen.getByText("Slots reset")).toBeInTheDocument();
  });

  it("hides internal rasa slots", () => {
    const { container } = renderWithProviders(
      <SlotEvent event={slotEvent({ name: "dialogue_stack" })} isSelected={false} />,
    );
    expect(container.textContent).toBe("");
  });
});
